// Kurzfenster zuerst: zwei Anfragen je Minute, drei je zehn Minuten.
// Das faengt den mehrfach geklickten Absendeknopf ab, bevor daraus Leads werden.
const GRENZE_IP_1MIN = 2;
const GRENZE_IP_10MIN = 3;
const GRENZE_IP_60MIN = 8;
const GRENZE_MAIL_24H = 5;
const GRENZE_BESTAETIGUNG_24H = 2;

const v = $('Eingaben validieren').first().json;
const res = $input.first().json || {};

let zeilen = [];
let pruefungFehler = null;

if (res.statusCode && res.statusCode >= 300) {
  pruefungFehler = 'HTTP ' + res.statusCode + ': ' + JSON.stringify(res.body || '').slice(0, 300);
} else if (Array.isArray(res.body)) {
  zeilen = res.body;
} else {
  pruefungFehler = 'Unerwartete Antwort der Frequenzabfrage';
}

const jetzt = new Date(v.receivedAt).getTime();
function innerhalb(zeile, minuten) {
  const t = new Date(zeile.created_at).getTime();
  if (!isFinite(t)) return false;
  const alter = jetzt - t;
  return alter <= minuten * 60000 && alter >= -60000;
}

// Der eigene Beleg wurde soeben geschrieben und darf sich nicht selbst zaehlen.
const andere = zeilen.filter(function (z) { return z && z.external_id !== v.executionId; });

const ipHash = v.ipHash || null;
const ip1 = ipHash ? andere.filter(function (z) { return z.ip_hash === ipHash && innerhalb(z, 1); }).length : 0;
const ip10 = ipHash ? andere.filter(function (z) { return z.ip_hash === ipHash && innerhalb(z, 10); }).length : 0;
const ip60 = ipHash ? andere.filter(function (z) { return z.ip_hash === ipHash && innerhalb(z, 60); }).length : 0;
const mail24 = andere.filter(function (z) { return String(z.email || '').toLowerCase() === v.email && innerhalb(z, 1440); }).length;

let gedrosselt = false;
let grund = null;

if (!pruefungFehler) {
  if (ip1 >= GRENZE_IP_1MIN) {
    gedrosselt = true;
    grund = 'Mehr als ' + GRENZE_IP_1MIN + ' Anfragen derselben Herkunft in einer Minute';
  } else if (ip10 >= GRENZE_IP_10MIN) {
    gedrosselt = true;
    grund = 'Mehr als ' + GRENZE_IP_10MIN + ' Anfragen derselben Herkunft in zehn Minuten';
  } else if (ip60 >= GRENZE_IP_60MIN) {
    gedrosselt = true;
    grund = 'Mehr als ' + GRENZE_IP_60MIN + ' Anfragen derselben Herkunft in einer Stunde';
  } else if (mail24 >= GRENZE_MAIL_24H) {
    gedrosselt = true;
    grund = 'Mehr als ' + GRENZE_MAIL_24H + ' Anfragen derselben Adresse in 24 Stunden';
  }
}

// Die Bestaetigungsmail geht an eine vom Absender frei gewaehlte Adresse. Sie bekommt
// deshalb eine eigene, engere Grenze, unabhaengig von der Drosselung des Vorgangs.
const bestaetigungErlaubt = pruefungFehler ? true : (mail24 < GRENZE_BESTAETIGUNG_24H);

return [{
  json: {
    gedrosselt: gedrosselt,
    grund: grund,
    bestaetigungErlaubt: bestaetigungErlaubt,
    pruefungFehler: pruefungFehler,
    zaehler: { ip1: ip1, ip10: ip10, ip60: ip60, mail24: mail24, betrachtet: andere.length },
    ipHash: ipHash
  }
}];

// Der Score-Node berechnet Bewertung und Kontaktfelder bereits, legt sie aber
// unter raw ab. lead_intake_verarbeiten liest sie nur auf oberster Ebene von
// p_payload. Dieser Node hebt sie dorthin und laesst alles andere unveraendert.

const SOURCE_ID_WEBSITE_FORMULAR = '6a46dc45-5c7b-46de-a439-b2ccb11b2d27';
const ERLAUBTE_PRIORITAETEN = ['a_sehr_hoch', 'b_hoch', 'c_mittel', 'd_niedrig', 'e_pruefen'];

function text(wert) {
  const s = String(wert === null || wert === undefined ? '' : wert).trim();
  return s || null;
}

return $input.all().map(function (item) {
  const json = item.json;
  const rpcBody = json.rpcBody;
  if (!rpcBody || !rpcBody.p_payload) {
    return { json: json };
  }

  const p = rpcBody.p_payload;
  const raw = p.raw || {};
  const kontakt = raw.kontakt || {};
  const anfrage = raw.anfrage || {};
  const bewertung = raw.bewertung || {};

  // Das Formular liefert oft nur ein Namensfeld. Letztes Wort gilt als Nachname.
  let vorname = text(kontakt.vorname);
  let nachname = text(kontakt.nachname);
  if (!vorname && !nachname) {
    const teile = (text(kontakt.name) || '').split(/\s+/).filter(Boolean);
    if (teile.length === 1) {
      nachname = teile[0];
    } else if (teile.length > 1) {
      vorname = teile.slice(0, -1).join(' ');
      nachname = teile[teile.length - 1];
    }
  }

  const punkte = Number(bewertung.score);
  const prio = text(bewertung.prioritaet_vorschlag);

  p.score = Number.isFinite(punkte) ? Math.max(0, Math.min(100, Math.round(punkte))) : null;
  p.priority = ERLAUBTE_PRIORITAETEN.indexOf(prio) >= 0 ? prio : 'e_pruefen';
  p.score_rationale = text(bewertung.begruendung);
  p.source_id = SOURCE_ID_WEBSITE_FORMULAR;
  p.topic = text(anfrage.thema) || 'Webanfrage';
  p.first_name = vorname;
  p.last_name = nachname;
  p.position = text(kontakt.position);

  return { json: Object.assign({}, json, { rpcBody: rpcBody }) };
});
